<div class="tabs"><a class="tab {{ !request('source') || request('source')==='all' ? 'active' : '' }}" href="{{ route('parts.index') }}">ყველა შეთავაზება</a><a class="tab {{ request('source')==='store' ? 'active' : '' }}" href="{{ route('parts.index',['source'=>'store']) }}">MotoHub მაღაზია</a><a class="tab {{ request('source')==='marketplace' ? 'active' : '' }}" href="{{ route('parts.index',['source'=>'marketplace']) }}">მომხმარებლების განცხადებები</a><a class="tab {{ request('condition')==='new' ? 'active' : '' }}" href="{{ route('parts.index',['condition'=>'new']) }}">ახალი</a><a class="tab {{ request('condition')==='used' ? 'active' : '' }}" href="{{ route('parts.index',['condition'=>'used']) }}">მეორადი</a></div>
</section>
<div class="layout">
<aside class="filters"><h2>ძებნის ფილტრები</h2>
<form method="GET" action="{{ route('parts.index') }}">
<input type="hidden" name="q" value="{{ $search }}">
<div class="field"><label for="source">წყარო</label><select id="source" name="source"><option value="all">ყველა</option><option value="store" @selected(($filters['source'] ?? 'all')==='store')>MotoHub მაღაზია</option><option value="marketplace" @selected(($filters['source'] ?? 'all')==='marketplace')>განცხადებები</option></select></div>
<div class="field"><label for="brand">ნაწილის ბრენდი</label><select id="brand" name="brand"><option value="">ყველა ბრენდი</option>@foreach($brands as $brand)<option value="{{ $brand }}" @selected(($filters['brand'] ?? '')===$brand)>{{ $brand }}</option>@endforeach</select></div>
<div class="field"><label for="category">კატეგორია</label><select id="category" name="category"><option value="">ყველა კატეგორია</option>@foreach($categories as $category)<option value="{{ $category }}" @selected(($filters['category'] ?? '')===$category)>{{ $category }}</option>@endforeach</select></div>
<div class="field"><label for="part_type">ნაწილის ტიპი</label><select id="part_type" name="part_type"><option value="">ყველა ტიპი</option><option value="oem" @selected(($filters['part_type'] ?? '')==='oem')>ორიგინალი (OEM)</option><option value="aftermarket" @selected(($filters['part_type'] ?? '')==='aftermarket')>Aftermarket</option><option value="used" @selected(($filters['part_type'] ?? '')==='used')>მეორადი</option></select></div>
<div class="field"><label for="motorcycle_brand">მოტოციკლის ბრენდი</label><input id="motorcycle_brand" name="motorcycle_brand" list="motorcycle-brands" value="{{ $filters['motorcycle_brand'] ?? '' }}" placeholder="მაგ. Yamaha"><datalist id="motorcycle-brands">@foreach($motorcycleBrands as $mb)<option value="{{ $mb }}">@endforeach</datalist></div>
<div class="field"><label for="motorcycle_model">მოდელი</label><input id="motorcycle_model" name="motorcycle_model" value="{{ $filters['motorcycle_model'] ?? '' }}" placeholder="მაგ. R1"></div>
<div class="field"><label for="motorcycle_year">გამოშვების წელი</label><input id="motorcycle_year" type="number" min="1900" max="2100" name="motorcycle_year" value="{{ $filters['motorcycle_year'] ?? '' }}" placeholder="მაგ. 2016"></div>
<div class="field"><label for="engine_cc">ძრავის მოცულობა (cc)</label><input id="engine_cc" type="number" min="1" max="10000" name="engine_cc" value="{{ $filters['engine_cc'] ?? '' }}" placeholder="მაგ. 1000"></div>
<div class="field"><label>მდგომარეობა</label><select name="condition"><option value="">ყველა</option><option value="new" @selected(($filters['condition'] ?? '')==='new')>ახალი</option><option value="used" @selected(($filters['condition'] ?? '')==='used')>მეორადი</option></select></div>
<div class="field"><label>ფასი (₾)</label><div class="row2"><input type="number" min="0" step=".01" name="min_price" value="{{ $filters['min_price'] ?? '' }}" placeholder="დან"><input type="number" min="0" step=".01" name="max_price" value="{{ $filters['max_price'] ?? '' }}" placeholder="მდე"></div></div>
<div class="actions"><button class="btn">ფილტრების გამოყენება</button><a class="btn ghost" href="{{ route('parts.index') }}">გასუფთავება</a></div>
</form></aside>
<section><div class="result-head"><h2>ნაწილების შეთავაზებები</h2><span class="muted">{{ $parts->total() }} შედეგი</span></div>
<div class="grid">
@forelse($parts as $part)
<article class="card"><div class="photo">@if($part['image_url'])<img src="{{ $part['image_url'] }}" alt="{{ $part['title'] }}" loading="lazy">@else<span class="no-photo">MOTOHUB / PARTS</span>@endif
<span class="tag">{{ $part['source']==='store' ? 'MOTOHUB მაღაზია' : ($part['condition']==='new' ? 'ახალი განცხადება' : 'მეორადი განცხადება') }}</span></div>
<div class="body"><div class="category">{{ $part['category'] ?: ($part['brand'] ?: 'მოტონაწილი') }}</div><h3>{{ $part['title'] }}</h3>
<div class="spec">@if($part['brand'])ბრენდი: {{ $part['brand'] }} · @endif{{ $part['part_type']==='oem' ? 'ორიგინალი OEM' : ($part['part_type']==='aftermarket' ? 'Aftermarket' : '') }}<br>
@if($part['motorcycle_brand'] || $part['motorcycle_model'])თავსებადია: {{ trim(($part['motorcycle_brand'] ?? '').' '.($part['motorcycle_model'] ?? '')) }} @if($part['motorcycle_year'])· {{ $part['motorcycle_year'] }} @endif @if($part['engine_cc'])· {{ $part['engine_cc'] }} cc @endif
@else{{ $part['compatible_motorcycle'] ?: 'თავსებადობა დასაზუსტებელია' }}@endif</div>
<div class="bottom"><div><div class="price">₾{{ number_format((float)$part['price'],2) }}</div><div class="seller">{{ $part['seller_name'] }} @if($part['stock'] !== null)· მარაგი: {{ $part['stock'] }} @endif</div></div></div>
<a class="details" href="{{ route('parts.show',[$part['source'],$part['id']]) }}">დეტალების ნახვა ↗</a></div></article>
