</div>
@if($parts->hasPages())<div class="pagination">{{ $parts->links() }}</div>@endif
</section></div></main>
<footer><div class="wrap">© {{ date('Y') }} MotoHub — მოტოციკლებისა და ნაწილების ბაზარი.</div></footer>
